  CHECK_SEGMENT_READONLY_RETURN_STATUS;

  if (wal_file_ == nullptr || !wal_file_->has_record()) {
    return Status::OK();
  }

  if (wal_file_) {
    if (wal_file_->flush() != 0) {
      LOG_ERROR("WAL flush failed: segment[%d]", id());
      return Status::InternalError("Failed to flush wal");
    }
  }

  Status s;

