bool SegmentImpl::SegmentIndexFilter::is_filtered(uint64_t id) const {
  auto impl = impl_.lock();
  if (!impl) return false;
  auto result = impl->get_global_doc_id(id);
  if (!result.has_value()) {
    return false;
